// The two Atlas mod keys PM trusts, pinned (copied from PM's src-tauri/src/mods/keys.rs
// ATLAS_MOD_KEYS, generated by Bobby 2026-11-05). A one-way door: PM trusts these until a signed
// revocation says otherwise. The sign job signs with the MAIN key only; the rollover key is offline and
// never in CI. test/minisign.test.mjs holds this table to its ids, and test/rules.test.mjs (with PM_CHECKOUT) to PM's keys.rs.

import { parsePublicKey } from "./minisign.mjs";
import { refuse } from "./rules.mjs";

export const ATLAS_MOD_KEYS = [
  { role: "main", id: "95B83457064D517B", public: "RWR7UU0GVzS4lT3ufWzzf1KvC/kqXW/23dyEdYpTHVvpHOg4d4LrMRTe" },
  { role: "rollover", id: "993CE0152A3E4E8C", public: "RWSMTj4qFeA8maIDkSNH7pMwICiuA2PEmjQOEyAwn8PDXHA5ztfNy8qW" },
];

/** Both pinned public keys, parsed, in PM's order; each key must decode to the id the table names. */
export function pinnedPublicKeys() {
  return ATLAS_MOD_KEYS.map((k) => {
    const key = parsePublicKey(k.public);
    if (key.id !== k.id) refuse(`the pinned ${k.role} key decodes to ${key.id}, not ${k.id}`);
    return { ...key, role: k.role };
  });
}

export const mainPublicKey = () => pinnedPublicKeys().find((k) => k.role === "main");
